/* Register texture command indices in one of the record's five-slot arrays. */
void *func_15195AA8(s32 displayList, s32 assetId, s32 doubleSize,
                  s32 occurrence, s32 state, s32 secondary,
                  s32 field12, s32 field13) {
    s32 packedSize;
    s32 index;
    s32 searchOccurrence;
    s32 tileCount;
    s32 slot;
    s32 packedScale;
    u8 *record = NULL;

    searchOccurrence = occurrence;
    if (displayList == 0) {
        return 0;
    }
    if (occurrence == -1) {
        searchOccurrence = 0;
    }
    do {
        index = func_15195868((u8 *)displayList, assetId, searchOccurrence, &tileCount);
        if (index == -1) {
            occurrence = 0;
        } else {
            if (assetId == 0) {
                assetId = D_800E08F0;
            }
            record = (u8 *)D_800E08E8;
            packedSize = *(s32 *)((u8 *)displayList + (index << 3) + 4);
            packedScale = *(s32 *)((u8 *)displayList + (index << 3));
            while (record != NULL && *(s16 *)(record + 8) != 0) {
                record = *(u8 **)(record + 4);
            }
            if (record == NULL) {
                record = (u8 *)func_15195984(assetId, packedSize, packedScale, doubleSize);
                if (record != NULL) {
                    record[0x12] = field12;
                    record[0x13] = field13;
                    state = 0;
                } else {
                    return 0;
                }
            } else {
                index = func_15195A84(index, (s32)record, packedSize, doubleSize);
                state = 0;
            }
            if (record[0x14] < tileCount) {
                record[0x14] = tileCount;
            }
            searchOccurrence++;
            if (secondary == 0) {
                slot = state;
                while (slot < 5 && ((s16 *)(record + 0x1C))[slot] != -1) {
                    slot++;
                }
                if (slot < 5) {
                    ((s16 *)(record + 0x1C))[slot] = index;
                    record[0x30 + slot] = tileCount;
                }
            } else {
                slot = state;
                while (slot < 5 && ((s16 *)(record + 0x26))[slot] != -1) {
                    slot++;
                }
                if (slot < 5) {
                    ((s16 *)(record + 0x26))[slot] = index;
                    record[0x35 + slot] = tileCount;
                }
            }
        }
    } while (occurrence == -1);
    if (assetId == D_800E08F0) {
        D_800E08F0--;
    }
    return record;
}

/* Find the actor's active group record and fill its two optional float pairs. */
s32 func_15022024(f32 *first, f32 *second, s32 actorIndex, s32 group) {
    s32 count;
    s32 index;
    u16 *active;
    u8 *tag;
    u8 *record;
    f32 missing;

    if (PAIR_GATE_49D30[group] != 1) {
        return 0;
    }
    count = PAIR_COUNT_49D30[group];
    index = 0;
    if (count <= 0) {
        return 0;
    }
    active = PAIR_ACTIVE_49D30[group];
    do {
        if (*active != 0) {
            tag = PAIR_TAGS_49D30[group] + index * 8;
            if (*(u16 *)tag == 2 &&
                PAIR_ACTORS_49D30[actorIndex * 0x32C + 0x3B] == tag[2]) {
                missing = D_80096A14;
                first[1] = 0.0f;
                second[1] = 0.0f;
                first[0] = 0.0f;
                second[0] = 0.0f;
                record = PAIR_RECORDS_49D30[group] + index * 0x44;
                if (*(f32 *)(record + 0x3C) != missing) {
                    second[0] = *(f32 *)(record + 0x3C);
                    second[1] = second[0];
                    /* Retail reloads the table only after the output stores. */
                    record = PAIR_RECORD_RELOAD_49D30(group) + index * 0x44;
                }
                if (*(f32 *)(record + 0x40) != missing) {
                    first[0] = *(f32 *)(record + 0x40);
                    first[1] = first[0];
                }
                return 1;
            }
        }
        index++;
        active++;
    } while (index < count);
    return 0;
}
